WITH src AS (SELECT *, CEIL(unit_price) AS unit_price_whole FROM order_items WHERE unit_price <= 230 AND order_id = 32 AND quantity BETWEEN 7 AND 8), order_items_stats AS (SELECT CASE WHEN unit_price >= 440 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END AS unit_price_bucket, order_id, ROUND(AVG(unit_price), 2) AS avg_unit_price, MIN(quantity) AS min_quantity FROM src GROUP BY CASE WHEN unit_price >= 440 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END, order_id) SELECT unit_price_bucket, order_id, avg_unit_price, min_quantity FROM order_items_stats WHERE min_quantity < 3.9 ORDER BY unit_price_bucket DESC
